// Protocol semantics, algorithms and database concepts.
for (const [code, reason, wrong] of [
    [201, T('Created', 'Created (ressource créée)', 'Created (Ressource erstellt)'), [200, 202, 204]],
    [204, T('No Content', 'No Content (sans contenu)', 'No Content (kein Inhalt)'), [200, 206, 304]],
    [301, T('Moved Permanently', 'Moved Permanently (déplacement permanent)', 'Moved Permanently (dauerhaft verschoben)'), [302, 303, 307]],
    [401, T('Unauthorized', 'Unauthorized (authentification requise)', 'Unauthorized (Authentifizierung erforderlich)'), [403, 404, 409]],
    [403, T('Forbidden', 'Forbidden (accès interdit)', 'Forbidden (Zugriff verboten)'), [401, 405, 503]],
    [409, T('Conflict', 'Conflict (conflit avec l’état de la ressource)', 'Conflict (Konflikt mit dem Ressourcenzustand)'), [404, 408, 410]],
    [503, T('Service Unavailable', 'Service Unavailable (service indisponible)', 'Service Unavailable (Dienst nicht verfügbar)'), [500, 501, 502]],
    [206, T('Partial Content', 'Partial Content (contenu partiel)', 'Partial Content (Teilinhalt)'), [200, 204, 202]],
]) add(`http-${code}`, 'technology', T(`Which HTTP status code has the reason phrase “${reason[0]}”?`, `Quel code HTTP correspond à « ${reason[1]} » ?`, `Welcher HTTP-Statuscode entspricht „${reason[2]}“?`), [code, ...wrong], 'medium');
